import{_ as t,c as p,o as a,ag as o}from"./chunks/framework.DPDPlp3K.js";const f=JSON.parse('{"title":"リポジトリを爆破しよう","description":"","frontmatter":{},"headers":[],"relativePath":"text/chapter-2/delete-repo.md","filePath":"text/chapter-2/delete-repo.md"}'),r={name:"text/chapter-2/delete-repo.md"};function d(s,e,i,l,c,n){return a(),p("div",null,e[0]||(e[0]=[o('<h1 id="リポジトリを爆破しよう" tabindex="-1">リポジトリを爆破しよう <a class="header-anchor" href="#リポジトリを爆破しよう" aria-label="Permalink to &quot;リポジトリを爆破しよう&quot;">​</a></h1><p>Git 講習会本編はこれにて終了です。お疲れ様でした。</p><p>……ですが、この講習会が終わったあとの皆さんの Gitea ページを想像してみてください。そこには、練習用に適当な名前で生やした「mydrive」や、実験の跡が残る無数のブランチが放置されることになります。Git 自体は壊れませんが、放置されたリポジトリは管理の手間を増やし、皆さんの作業スペースを散らかす原因になります。 そこで最後は、あえて「<strong>壊れないはずのリポジトリ</strong>」を木っ端微塵に消し去る「<strong>爆破</strong>」の儀式を行ってお別れしましょう。</p><h2 id="跡形もなく消し去る方法" tabindex="-1">跡形もなく消し去る方法 <a class="header-anchor" href="#跡形もなく消し去る方法" aria-label="Permalink to &quot;跡形もなく消し去る方法&quot;">​</a></h2><p>Gitea のリポジトリのページから右上の「設定」タブを開きます。</p><p><img src="https://md.trap.jp/uploads/upload_7ee212e9a0926125662d34f3fab024b0.png" alt=""></p><p>一番下までスクロールして、「このリポジトリの削除」を選択します。</p><p><img src="https://md.trap.jp/uploads/upload_fa5f93f8fe9e6ff70f289f15e0bb72de.png" alt=""></p><p>指示に従ってリポジトリ名を入力すれば削除ができます。</p><p><img src="https://md.trap.jp/uploads/upload_4c11d55c4b18b54ef1e5d0e7b3267286.png" alt=""></p><div class="tip custom-block"><p class="custom-block-title">お疲れ様でした！ ……本当に？</p><p>これにて、Gitea 上の「mydrive」は宇宙の塵となりました。ブラウザでリポジトリの URL を叩いても、そこには「404 Not Found」という虚無が広がっているはずです。</p><p>しかし、あなたの手元のターミナルを見てください。</p><p>そこには、先ほどまで編集していたファイルがあり、<code>git log</code> を打てばあんなに苦労してマージした履歴も、解決したコンフリクトの跡も、完璧に保存されています。</p><p>これが Git が「分散型」と呼ばれる理由です。 ホスティングサービス（Gitea）上にあるのはあくまでアップロードされたデータであり、リポジトリの完全なデータはみなさんの PC（ローカル環境）に残っています。もし必要であれば、新しくリモートリポジトリを作成して <code>git push</code> を行うだけで、すぐに元の状態を復元することができます。</p><p>本当の Git の力（と、一度刻んだ履歴はそう簡単には消えないという恐ろしさ）を実感していただけたでしょうか？</p></div><hr><p>次のページで Git 講習会本編は本当に終了です！</p>',13)]))}const m=t(r,[["render",d]]);export{f as __pageData,m as default};
